__NUXT_JSONP__("/think-tanks/eventos/la_corrupcion_y_la_gobernanza_democratica_son_desafios_que_requieren_mas_participacion_del_sur_global", (function(a,b,c,d,e,f,g,h,i,j,k){return {data:[{post:{slug:"la_corrupcion_y_la_gobernanza_democratica_son_desafios_que_requieren_mas_participacion_del_sur_global",title:"La corrupción y la gobernanza democrática son desafíos que requieren más participación del Sur Global",date:"2023-10-26T18:07:20.509Z",img:"https:\u002F\u002Fucarecdn.com\u002Fc88c67fe-88eb-462d-b2db-a37e08228f45\u002F","img-alt":"Liliana Alvarado ",autor:"Ethos",category:"think-tanks",extracto:"La directora de Ethos, Liliana Alvarado, participó en la conferencia de Southern Voice, y destacó que la corrupción pone en riesgo el futuro de la democracia en el Sur Global.",galeria:["https:\u002F\u002Fucarecdn.com\u002F66db38bd-9cde-47e1-89fb-38ee984ff027\u002F","https:\u002F\u002Fucarecdn.com\u002Fa458b278-8b8f-4e42-9f7d-d040bcb91475\u002F"],toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"En el marco de los festejos por su décimo aniversario, "},{type:b,tag:e,props:{href:"https:\u002F\u002Fsouthernvoice.org\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Southern Voice"}]},{type:a,value:" realizó su conferencia 2023 en Nairobi, Kenia, denominada «Impulsando la próxima década de desarrollo sostenible», un espacio para identificar áreas de la agenda de desarrollo global que requieren particularmente una mayor cooperación internacional y una mayor influencia de los países del Sur Global."},{type:b,tag:j,props:{},children:[]},{type:a,value:d},{type:b,tag:j,props:{},children:[]},{type:a,value:"\nLiliana Alvarado, directora de Ethos, participó en este evento, en el panel “Brechas en el discurso sobre el desarrollo: Respuestas a los hallazgos”, en el cual señaló que los desafíos globales que requieren más participación del Sur Global son el combate a la corrupción, uno de los peores problemas que afecta a la región de Latinoamérica, así como la gobernanza democrática. Ambos puntos, afirmó, están profundamente relacionados."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“Una de las razones por las que las políticas públicas en salud, educación, seguridad, pobreza, en nuestros países no están funcionando es por la corrupción. En muchos casos, implica un desvío de recursos que impide que las acciones y programas del gobierno contribuyan a educar, brindar seguridad y aliviar la pobreza”, expresó. También indicó que en algunos países, la corrupción afecta incluso el sistema electoral, los procesos políticos y las elecciones."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"“Cuando todos estos elementos convergen, es natural que los ciudadanos comiencen a cuestionar la eficacia de las democracias y se inclinen por apoyar regímenes más radicales o autoritarios. Por lo tanto, es esencial reconocer que la corrupción plantea un desafío a los sistemas democráticos”, dijo."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Asimismo, enfatizó que la corrupción plantea un desafío a los regímenes democráticos, por lo que es indispensable dar mayor visibilidad y atención a ambos problemas, porque la gravedad del primero está poniendo en peligro el futuro de varios regímenes democráticos en el Sur Global."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En el panel también estuvieron presentes Gilles Yabi, de "},{type:b,tag:e,props:{href:"http:\u002F\u002Fwww.wathi.org",rel:[f,g,h],target:i},children:[{type:a,value:"WATHI"}]},{type:a,value:", en Senegal; Mirza Hassan, de "},{type:b,tag:e,props:{href:"https:\u002F\u002Fbigd.bracu.ac.bd\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"BIGD"}]},{type:a,value:", en Bangladesh; y Julie Kofoed, de "},{type:b,tag:e,props:{href:"https:\u002F\u002Funfoundation.org\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"United Nations Foundation"}]},{type:a,value:", Estados Unidos."}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fla_corrupcion_y_la_gobernanza_democratica_son_desafios_que_requieren_mas_participacion_del_sur_global",extension:".md",createdAt:k,updatedAt:k}}],fetch:{},mutations:[]}}("text","element","p","\n","a","nofollow","noopener","noreferrer","_blank","br","2023-12-09T02:06:39.561Z")));